// GitHub Pages cannot set COOP/COEP headers. This scope-local worker adds
// isolation to network responses; it deliberately does not cache application files.
self.addEventListener('install', () => self.skipWaiting());
self.addEventListener('activate', event => event.waitUntil(self.clients.claim()));
self.addEventListener('fetch', event => {
 const request=event.request;
 if(new URL(request.url).origin!==self.location.origin || (request.cache==='only-if-cached'&&request.mode!=='same-origin'))return;
 event.respondWith(fetch(request).then(response=>{
  if(response.status===0)return response;
  const headers=new Headers(response.headers);
  headers.set('Cross-Origin-Opener-Policy','same-origin');
  headers.set('Cross-Origin-Embedder-Policy','require-corp');
  return new Response(response.body,{status:response.status,statusText:response.statusText,headers});
 }));
});

import http from 'node:http';import fs from 'node:fs';import path from 'node:path';import {fileURLToPath} from 'node:url';import {spawn} from 'node:child_process';
const root=path.dirname(fileURLToPath(import.meta.url));const port=Number(process.argv.find(x=>/^\d+$/.test(x))??8090);
if(!Number.isInteger(port)||port<1||port>65535)throw Error('Port must be between 1 and 65535.');
const mime={'.html':'text/html; charset=utf-8','.js':'text/javascript; charset=utf-8','.mjs':'text/javascript; charset=utf-8','.css':'text/css; charset=utf-8','.json':'application/json; charset=utf-8','.cu':'text/plain; charset=utf-8','.wgsl':'text/plain; charset=utf-8','.png':'image/png','.webp':'image/webp','.md':'text/plain; charset=utf-8'};
const server=http.createServer((req,res)=>{
 if(req.method!=='GET'&&req.method!=='HEAD'){res.writeHead(405);res.end();return;}
 let pathname;try{pathname=decodeURIComponent(new URL(req.url,'http://localhost').pathname);}catch{res.writeHead(400);res.end();return;}
 const target=path.resolve(root,'.'+(pathname.endsWith('/')?pathname+'index.html':pathname));
 if(target!==root&&!target.startsWith(root+path.sep)){res.writeHead(403);res.end();return;}
 fs.stat(target,(err,stat)=>{if(err||!stat.isFile()){res.writeHead(404);res.end('Not found');return;}
  res.writeHead(200,{'Content-Type':mime[path.extname(target)]??'application/octet-stream','Content-Length':stat.size,'Cache-Control':'no-cache','X-Content-Type-Options':'nosniff'});
  if(req.method==='HEAD')res.end();else{const stream=fs.createReadStream(target);stream.on('error',()=>res.destroy());stream.pipe(res);}
 });
});
server.on('error',e=>{console.error(e.code==='EADDRINUSE'?`Port ${port} is already in use. Try: node server.mjs ${port+1}`:e);process.exitCode=1;});
server.listen(port,'127.0.0.1',()=>{const url=`http://localhost:${port}`;console.log(`\nWaterCuda — Infinite islands.\n${url}\nKeep this terminal open. Ctrl+C stops the server.\n`);if(process.argv.includes('--open')){const command=process.platform==='win32'?'cmd':process.platform==='darwin'?'open':'xdg-open';const args=process.platform==='win32'?['/c','start','',url]:[url];const child=spawn(command,args,{detached:true,stdio:'ignore'});child.on('error',()=>{});child.unref();}});

@echo off
cd /d "%~dp0"
call npm run build
if errorlevel 1 (pause & exit /b 1)
node server.mjs 8090 --open
pause

@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Manrope:wght@400;500;600;700;800&display=swap');
.project-links{font-size:10px;text-align:center;margin:14px 0}.project-links a{color:var(--muted);text-underline-offset:3px}.project-links a:hover{color:var(--accent)}
:root{color-scheme:dark;--ink:#e8f0ee;--muted:#adc3c1;--line:#c5e5df22;--accent:#bde3ce}*{box-sizing:border-box}body{margin:0;background:#0e2631;color:var(--ink);font:13px 'DM Sans',Arial,sans-serif;overflow:hidden}#view{width:100vw;height:100vh;display:block;touch-action:none;cursor:grab}#view:active{cursor:grabbing}.hud{position:fixed;z-index:2}header{left:42px;right:42px;top:29px;display:flex;align-items:center;gap:26px}.brand{text-decoration:none;color:#fff;letter-spacing:3px;font:800 17px Manrope,Arial}.brand>span:last-child{font-weight:400;opacity:.6}.mark{font:40px Georgia;vertical-align:middle;margin-right:12px}.edition{font-size:9px;letter-spacing:2px;opacity:.58;margin-left:22px}.round{margin-left:auto;border-radius:50%;width:37px;height:37px}button,select,input{font:inherit;color:inherit}button,select{border:1px solid var(--line);background:#d6f5ed09;border-radius:6px;padding:9px 12px;cursor:pointer}button:hover{background:#d6f5ed20;border-color:#c5e5df65}button:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid var(--accent);outline-offset:3px}main{left:48px;top:22%;pointer-events:none;text-shadow:0 2px 25px #051c2a70}.eyebrow{display:flex;align-items:center;font-size:9px;letter-spacing:2.3px;gap:10px}.live{width:5px;height:5px;background:#bfe6ce;border-radius:50%;box-shadow:0 0 12px #bfe6ce}h1{font:500 clamp(42px,5vw,77px)/1.08 Manrope,Arial;margin:24px 0 22px;letter-spacing:-4px}h1 em{font:italic 1.06em Georgia,serif;letter-spacing:-2px}.intro{color:#d5e6e7b0;font-size:13px;line-height:1.8}.location{border-left:1px solid #d5e6e760;margin-top:34px;padding-left:15px;display:grid;gap:8px;font-size:11px;letter-spacing:2px}.location small{font-size:8px;color:#d5e6e798;letter-spacing:1.8px}aside{right:38px;top:120px;width:264px;background:linear-gradient(130deg,#0a2734e8,#102b35c9);backdrop-filter:blur(24px);border:1px solid #d5e6e726;border-radius:12px;padding:23px;box-shadow:0 20px 60px #041c2e22;max-height:calc(100vh - 210px);overflow:auto}.panel-heading{display:flex;justify-content:space-between;border-bottom:1px solid var(--line);padding-bottom:19px;margin-bottom:21px;font-size:9px;letter-spacing:2px}.dot{color:var(--accent);font-size:8px}aside>label{display:flex;justify-content:space-between;margin:20px 0 11px;font-size:11px;color:var(--muted)}label span,output{font-size:10px;color:#e8f0ee7c}.seed-row{display:flex;gap:8px}input[type=number]{width:100%;min-width:0;background:#01151d50;border:1px solid var(--line);border-radius:5px;padding:10px;letter-spacing:2px}input[type=range]{width:100%;height:3px;accent-color:var(--accent);cursor:pointer}input[type=checkbox]{accent-color:var(--accent)}.control-row{display:flex;align-items:center;justify-content:space-between;font-size:10px;margin-top:20px;color:var(--muted)}select{max-width:130px;font-size:10px;padding:6px}select option{background:#112c36}.views{display:flex;margin:24px 0 14px;gap:5px}.views button{flex:1;padding:8px 3px;font-size:10px;border-color:transparent}.views button.selected{border-color:#c5e5df44;background:#d6f5ed12}.primary{width:100%;background:var(--accent);color:#18382d;font-weight:600;text-align:left;padding:12px 14px}.primary:hover{background:#d1efdc}.primary span{float:right}.secondary{display:flex;justify-content:space-between;gap:4px;margin-top:10px}.secondary button{border:0;font-size:9px;padding:8px 3px;color:var(--muted)}details{margin-top:17px;border-top:1px solid var(--line);padding-top:15px;font-size:10px;color:var(--muted)}summary{cursor:pointer}details p{line-height:1.7}details button{margin-top:12px;width:100%}pre{white-space:pre-wrap;font:10px/1.7 monospace}footer{bottom:26px;left:43px;right:40px;display:flex;justify-content:space-between;align-items:center;font-size:9px;color:#d5e6e7aa;letter-spacing:.5px}.keys{display:flex;align-items:center;gap:8px}.keys b{font-size:8px;color:#e8f0eed0;border:1px solid #d5e6e730;padding:5px;border-radius:3px;letter-spacing:1px}.keys i{width:12px}.performance{display:flex;gap:18px;font-size:8px}.performance span:first-child{color:#d8efd9}#loading{position:fixed;inset:0;z-index:10;background:#0d2633;display:grid;place-content:center;text-align:center;transition:opacity .6s}#loading.done{opacity:0;pointer-events:none}.loading-logo{font:100px Georgia;color:var(--accent)}h2{font:400 25px Manrope,Arial}#status{color:var(--muted);max-width:600px;line-height:1.6}#toast{position:fixed;bottom:80px;left:50%;transform:translateX(-50%);z-index:11;background:#0c2435e8;border-radius:6px;padding:12px 18px;opacity:0;pointer-events:none;transition:opacity .3s}#toast.visible{opacity:1}#restore{position:fixed;bottom:24px;right:24px;background:#102b35b0;z-index:3}body.clean .hud{display:none}@media(max-width:850px){header{left:20px;right:20px}.edition{display:none}main{left:25px;top:18%}h1{font-size:48px}aside{right:20px;top:95px;width:225px;padding:18px}footer{left:20px;right:20px}.keys{display:none}}@media(max-width:560px){main{top:100px}h1{font-size:39px;letter-spacing:-2px}.intro,.location,.eyebrow{display:none}aside{top:auto;bottom:65px;max-height:44vh;width:210px;padding:15px}.panel-heading{margin-bottom:10px;padding-bottom:10px}header .brand{font-size:14px}}
body::after{content:"";position:fixed;inset:0;z-index:1;pointer-events:none;background:linear-gradient(90deg,#03182575,transparent 34%),linear-gradient(0deg,#03182565,transparent 12%)}
.flight-button{width:100%;margin:0 0 8px;border-color:#bde3ce66;color:#c5e5cf}#flightStatus{display:block;font-size:8px;letter-spacing:1px;color:#b7c9c5;margin:0 0 14px}main{transition:opacity .3s,transform .3s}.exploring main{opacity:0;transform:translateX(-15px)}#view:focus{outline:none}#timings{color:#bde3ce;border-top:1px solid var(--line);padding-top:10px}

/* Keep the expanded optical controls usable on short and narrow viewports. */
aside.hud{max-height:calc(100dvh - 130px);overflow-y:auto;scrollbar-width:thin;scrollbar-color:#73918b transparent}#look{width:100%;margin:0 0 4px}.views{display:grid;grid-template-columns:repeat(3,minmax(0,1fr))}.views button{padding-left:4px;padding-right:4px}#caustics{width:auto}body.clean aside.hud{pointer-events:none}@media(max-height:760px){aside.hud{top:75px;max-height:calc(100dvh - 130px)}}

#startup-preview,#nis-preview{position:fixed;inset:0;width:100vw;height:100vh;pointer-events:none;z-index:1}

param([switch]$Run, [switch]$Test)
$ErrorActionPreference = 'Stop'
$nativeRoot = $PSScriptRoot
$vswhere = "${env:ProgramFiles(x86)}/Microsoft Visual Studio/Installer/vswhere.exe"
if (-not (Get-Command cl.exe -ErrorAction SilentlyContinue)) {
 if (-not (Test-Path -LiteralPath $vswhere)) { throw 'Install Visual Studio C++ build tools, or run from an x64 Native Tools prompt.' }
 $vsRoot = & $vswhere -latest -products * -requires Microsoft.VisualStudio.Component.VC.Tools.x86.x64 -property installationPath
 if (-not $vsRoot) { throw 'The Visual Studio Desktop development with C++ workload is required.' }
 $devCmd = Join-Path $vsRoot 'Common7/Tools/VsDevCmd.bat'
 $vars = & cmd.exe /d /c "call `"$devCmd`" -arch=x64 -host_arch=x64 >nul && set"
 if ($LASTEXITCODE -ne 0) { throw 'Visual Studio environment setup failed.' }
 foreach ($line in $vars) { if ($line -match '^([^=]+)=(.*)$') { [Environment]::SetEnvironmentVariable($matches[1],$matches[2],'Process') } }
}
if (-not (Get-Command nvcc.exe -ErrorAction SilentlyContinue)) { throw 'Install NVIDIA CUDA Toolkit and put nvcc on PATH.' }
& cmake -S $nativeRoot -B "$nativeRoot/build" -G Ninja -DCMAKE_BUILD_TYPE=Release -DCMAKE_CUDA_ARCHITECTURES=native
if ($LASTEXITCODE -ne 0) { throw 'CMake configuration failed.' }
& cmake --build "$nativeRoot/build"
if ($LASTEXITCODE -ne 0) { throw 'Native build failed.' }
if ($Test) { & ctest --test-dir "$nativeRoot/build" --output-on-failure; if ($LASTEXITCODE -ne 0) { throw 'Native GPU tests failed.' } }
if ($Run) { & "$nativeRoot/build/watercuda.exe" }

import {Engine} from './engine.js';
import {applySeaLook} from './sea-looks.js';
import {rebase,parseSeed,renderSize} from './world.js';
import {FlightInput,moveCamera,toggleHelm} from './flight.js';
import {WasmStartup} from './wasm-startup.js';
const $=id=>document.getElementById(id),canvas=$('view');
const camera=new Float32Array([340,160,100,-0.05,-0.10,0,1,-0.7,0.7,1,0,1,1.5,1,0,0,...new Array(24).fill(0)]);
const origin=new Int32Array([0,0,42,0]);
let engine,paused=false,drifting=false,speed=60,resizing=true,running=false,last=performance.now(),frames=0,lastStats=last,autoWidth=960,lastAdapt=0;
let toastTimer;
let startup,previewCanvas,gpuActive=false,startupFirst=false;
function toast(message){$('toast').textContent=message;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),3500);}
function preset(name){
 const views={ship:[682,16,612,-.70,-.035],coast:[1250,210,650,0.52,-0.10],aerial:[-300,1400,-300,0.70,-0.34],water:[1550,7,1100,0.52,0.025],shore:[1850,25,1250,0.15,-0.30],scrub:[2810.9,11.51,1131.74,0,-.20],bars:[3370,42,2770,-1.4,-.23],reef:[4377,-7,2784,0,-.12],coral:[4377,-7.3,2810.8,0,-.18],family:[4377,-6.5,2805,0,-.23]};
 const v=views[name];camera.set(v);camera[14]=name==='ship'?3:(name==='family'?2:(name==='coral'?1:0));if(name==='ship'){camera.set([650,0,650,0,0,0,0,100],16);camera[3]=-.6;camera[4]=-.18;camera[19]=camera[3];camera[32]=camera[19];camera[33]=camera[34]=0;speed=25;}else if(camera[14]>0)speed=2;origin[0]=0;origin[1]=0;rebase(camera,origin);input.clear();drifting=false;$('sail').innerHTML='Begin drift <span>→</span>';
 document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('selected',b.dataset.view===name));
}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>preset(b.dataset.view));
$('generate').onclick=()=>{try{origin[2]=parseSeed($('seed').value);preset('coast');toast('Archipelago generated · seed '+origin[2]);}catch(e){toast(e.message);}};
function syncLookControls(){
 $('wind').value=camera[6];$('windValue').value=camera[6].toFixed(1);$('sun').value=camera[8];$('sunValue').value=camera[8]<.35?'Golden hour':'Daylight';
 $('clarity').value=camera[12];$('clarityValue').value=camera[12].toFixed(2)+'×';$('azimuth').value=camera[7]*180/Math.PI;$('azimuthValue').value=Math.round(camera[7]*180/Math.PI)+'°';
}
function setLook(name){applySeaLook(camera,name);$('look').value=name;syncLookControls();}
function selectHour(hour){camera[8]=10+((hour-camera[5]/60)%24+24)%24;$('daycycle').checked=true;}
$('hour').oninput=e=>selectHour(Number(e.target.value));
$('daycycle').onchange=e=>{if(e.target.checked)selectHour(Number($('hour').value));else camera[8]=Number($('sun').value);};
$('weather').onchange=e=>{camera[15]=Number(e.target.value);};
$('look').onchange=e=>{$('daycycle').checked=false;setLook(e.target.value);toast('Sea and light updated');};
$('clarity').oninput=e=>{camera[12]=Number(e.target.value);$('clarityValue').value=camera[12].toFixed(2)+'×';};
$('azimuth').oninput=e=>{camera[7]=Number(e.target.value)*Math.PI/180;$('azimuthValue').value=e.target.value+'°';};
$('caustics').onchange=e=>camera[13]=Number(e.target.checked);
$('wind').oninput=e=>{camera[6]=Number(e.target.value);$('windValue').value=camera[6].toFixed(1);};
$('sun').oninput=e=>{$('daycycle').checked=false;camera[8]=Number(e.target.value);$('sunValue').value=camera[8]<.35?'Golden hour':'Daylight';};
$('reflections').onchange=e=>camera[9]=Number(e.target.checked);
$('debug').onchange=e=>camera[10]=Number(e.target.value);
$('quality').onchange=()=>resizing=true;window.addEventListener('resize',()=>resizing=true);
$('pause').onclick=()=>{paused=!paused;$('pause').textContent=paused?'Resume world':'Pause world';};
$('sail').onclick=()=>{drifting=!drifting;$('sail').innerHTML=drifting?'Stop drift <span>Ⅱ</span>':'Begin drift <span>→</span>';};
function toggleUI(){const clean=document.body.classList.toggle('clean');$('restore').hidden=!clean;}
$('hide').onclick=toggleUI;$('restore').onclick=toggleUI;
const input=new FlightInput(canvas,camera,{
 onShortcut:code=>{if(code==='KeyV'){toggleHelm(camera);toast(camera[14]===4?'Free flight � V to return to ship':'Ship controls');}if(code==='KeyB')preset('ship');if(code==='KeyH')toggleUI();if(code==='KeyF')input.capture();if(code==='Digit1')preset('coast');if(code==='Digit2')preset('aerial');if(code==='Digit3')preset('water');if(code==='Digit4')preset('shore');if(code==='Digit7')preset('reef');if(code==='Digit8')preset('coral');},
 onSpeed:delta=>{speed=Math.max(3,speed*Math.exp(-delta*.001));toast('Flight speed · '+Math.round(speed)+' m/s');},
 onLock:locked=>{$('fly').textContent=locked?'Flying · Esc to release':'Free camera · F';document.body.classList.toggle('exploring',locked);$('flightStatus').textContent=locked?'MOUSE LOOK · ESC TO RELEASE':'DRAG TO LOOK · F FOR MOUSE LOOK';}
});
$('fly').onclick=()=>{if(!input.capture())toast('Mouse capture unavailable here. Drag on the scene to look.');};
$('capture').onclick=async()=>{if(!gpuActive&&!startupFirst)return;try{const blob=gpuActive?await engine.capture():await startup.capture();const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='WaterCuda-'+origin[2]+'.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('Image saved');}catch(e){toast(e.message);}};
$('validate').onclick=async()=>{if(!engine)return;$('validate').disabled=true;$('checks').textContent='Running actual GPU fixtures…';try{const result=await engine.validate();$('checks').textContent=result.checks.map(([name,ok])=>(ok?'PASS':'FAIL')+'  '+name).join('\n');document.body.dataset.gpuTests=result.checks.every(([,ok])=>ok)?'passed':'failed';window.gpuValidation=result;}catch(e){$('checks').textContent=e.stack;document.body.dataset.gpuTests='failed';}finally{$('validate').disabled=false;}};
function advance(dt){
 if(!(paused&&camera[14]===3))moveCamera(camera,origin,input.keys,dt,speed,drifting);if(input.keys.size||input.drag)document.body.classList.add('exploring');if(!paused)camera[5]+=dt;
}
async function loop(now){
 if(!running)return;
 try{
  const dt=Math.min(.1,(now-last)/1000);last=now;
  if(document.hidden){requestAnimationFrame(loop);return;}
  advance(dt);
  if(!gpuActive){
   startup?.frame(camera,origin);
   $('position').textContent='CELL '+origin[0].toLocaleString()+' / '+origin[1].toLocaleString();$('altitude').textContent='ALTITUDE '+Math.round(camera[1])+' M · SEED '+origin[2];
   if(camera[8]>=10){const hour=((camera[8]-10+camera[5]/60)%24+24)%24;$('hour').value=hour;$('hourValue').value=String(Math.floor(hour)).padStart(2,'0')+':'+String(Math.floor(hour%1*60)).padStart(2,'0');}
   $('flightStatus').dataset.position=[origin[0],origin[1],...Array.from(camera.slice(0,5))].join(',');
   requestAnimationFrame(loop);return;
  }
  if($('quality').value==='auto'&&now-lastAdapt>2000&&engine.gpuMs){lastAdapt=now;const ms=engine.gpuMs;let next=autoWidth;if(ms>18)next=Math.max(512,Math.floor(autoWidth*Math.max(.8,Math.sqrt(15/ms))/64)*64);else if(ms<11)next=Math.min(1280,autoWidth+64);if(next!==autoWidth){autoWidth=next;resizing=true;}}
  if(resizing){resizing=false;const target=$('quality').value==='auto'?autoWidth:Number($('quality').value),{width,height}=renderSize(innerWidth,innerHeight,target);await engine.resize(width,height);$('resolution').textContent=width+' × '+height+' / WEBGPU';}
  if(engine.frame(camera,origin))frames++;
  if(now-lastStats>1000){$('fps').textContent=Math.round(frames*1000/(now-lastStats))+' FPS';frames=0;lastStats=now;
   if(camera[8]>=10){const hour=((camera[8]-10+camera[5]/60)%24+24)%24;$('hour').value=hour;$('hourValue').value=String(Math.floor(hour)).padStart(2,'0')+':'+String(Math.floor(hour%1*60)).padStart(2,'0');}
   $('position').textContent='CELL '+origin[0].toLocaleString()+' / '+origin[1].toLocaleString();$('altitude').textContent='ALTITUDE '+Math.round(camera[1])+' M · SEED '+origin[2];
   $('timings').textContent=engine.timings?engine.timings.map(t=>t.name+': '+t.ms.toFixed(2)+' ms').join('\n')+'\nGPU total: '+engine.gpuMs.toFixed(2)+' ms':'GPU timestamps unavailable';
   $('flightStatus').dataset.position=[origin[0],origin[1],...Array.from(camera.slice(0,5))].join(',');}
  requestAnimationFrame(loop);
 }catch(e){running=false;$('loading').classList.remove('done');$('status').textContent=e.message;console.error(e);}
}
try{
 const url=new URL(location.href);if(url.searchParams.has('seed')){origin[2]=parseSeed(url.searchParams.get('seed'));$('seed').value=origin[2];}
 const weatherModes={auto:0,clear:1,overcast:2,rain:3,storm:4};camera[15]=weatherModes[url.searchParams.get('weather')]??0;$('weather').value=String(camera[15]);
 window.waterCuda={get engine(){return engine;},camera,origin,preset,setLook,setRenderLoop(on){if(on&&!running){running=true;last=performance.now();requestAnimationFrame(loop);}else if(!on)running=false;}};
 setLook(['coastal','golden','swell'].includes(url.searchParams.get('look'))?url.searchParams.get('look'):'coastal');
 if(url.searchParams.get('clock')!=='manual'){const hour=Number(url.searchParams.get('hour')??12);selectHour(Number.isFinite(hour)?hour:12);}else $('daycycle').checked=false;
 preset(['coast','aerial','water','shore','scrub','bars','reef','coral','family','ship'].includes(url.searchParams.get('view'))?url.searchParams.get('view'):'coast');
 if(crossOriginIsolated && typeof SharedArrayBuffer!=='undefined' && url.searchParams.get('startup')!=='gpu'){
  previewCanvas=document.createElement('canvas');previewCanvas.id='startup-preview';previewCanvas.setAttribute('aria-hidden','true');canvas.after(previewCanvas);
  startup=new WasmStartup(previewCanvas,{
   onFrame:data=>{
    if(!startupFirst){startupFirst=true;document.body.dataset.backend='wasm';document.body.dataset.previewReady='true';$('loading').classList.add('done');}
    $('fps').textContent=Math.round(1000/data.ms)+' FPS';$('resolution').textContent=data.width+' × '+data.height+' / CPU'+(data.nis?' · NIS 2×':'')+' · preparing GPU';
   },
   onError:message=>{console.warn('WASM startup:',message);toast('CPU preview unavailable · preparing GPU');}
  });
 }
 running=true;last=performance.now();requestAnimationFrame(loop);
 // Give the CPU a chance to show the scene first, without making GPU startup
 // depend on a successful WASM download or a responsive worker.
 if(startup)await Promise.race([startup.first,new Promise(resolve=>setTimeout(resolve,2500))]);
